local a=require("ExcelTool")local b=a.Pack;local c=a.Sub;local d=a.LangGet;local e=a.Dmap;local f=require("Excels.Data.item_definition.skin")local g=f.tb;local h=f.get;g[403105]=b({e[17057],403105,22,97,189,"「いかなる時でも、心がスイーツを求める限り、おとぎの国のお茶会は、いつでも君をお招きするよ。\nあらゆる悩みと疲れを消し去る、特製魔法スイーツをお望みなら、俺の名前を呼んで。」",200031,2,"deco/character/403105",false,false,false,false,false,false,false,"0","shiyuanduihai_hxsw",false,0},h)g[403201]=b({e[46057],403201,false,98,190,false,200032,false,"deco/character/ailisha",302002,60,false,false,false,false,118,"0.949999988",false,false,false,false,false,false,false,"60,190,0.97","0,100,0.95","0,70,0.95","0,0,0.95","0,0,0.95","0,0,0.95","0,80,0.95","0,80,0.95","0,0,0.95",false,false,1888,968,422,1173,840,1735,2664,1173,840,1735,1099,"ailisha"},h)g[403202]=b({e[17034],403202,1,4,191,"「オオカミさん、見て見て！\n今年は大豊作だったから、おばあちゃんがたくさん送ってきてくれたんだ。\nオオカミさんにもどうぞって！ えへへっ。」",200032,1,"deco/character/ailisha_0",302002,60,false,false,false,false,false,"0",1829,941,410,438,442,3181,3346,578,645,2901,1261,false,false,false,false,false,false,false,false,false,false,false,false,"ailisha_0"},h)g[403203]=b({e[21034],403203,9,71,192,"「リサリサが羊を数えてあげるね。羊が1匹……2匹……さん……ふぁ～」",200032,2,"deco/character/ailisha_SY",false,false,1,false,false,false,false,false,false,false,false,"80,-130,1",1807,1006,382,808,468,2243,2378,808,696,2243,1261,false,false,false,false,false,false,false,false,false,false,false,false,"ailisha_sy"},h)g[403204]=b({e[23034],403204,6,89,193,"「オオカミさーん！　魚の丸揚げの甘酢あんかけを手土産に持ってきたよ！　オオカミさんのお腹が空いたら、リサリサとぽややんを食べないでお魚さんを食べてね！」",200032,2,"deco/character/403204",false,false,false,false,false,false,false,"0",false,false,false,false,"-85,0,1","-110,0,1",1852,876,361,1086,671,2090,2770,1086,671,2090,1146,1,5330,7065,2650,4950,6667,6667,6667,6667,6667,false,6667,"ailisha_cj",false,0},h)g[403205]=b({e[21034],403205,3,24,194,"「ガ、ガオー！　リサリサ、大勝利～……って、あわわわ！　オオカミさん避けてー！　むむ、このチェーンソーやっぱり重いよ～。……そうだ、明日からリサリサもオオカミさんと一緒にトレーニングしよっかな！　えへへ。」",200032,2,"deco/character/ailisha_WS",false,false,1,false,false,false,false,"0",false,false,false,"100,-220,1",1965,870,384,802,322,2546,2790,802,561,2546,1261,false,false,false,false,false,false,false,false,false,false,false,false,"ailisha_ws"},h)g[403206]=b({e[23034],403206,16,44,195,"「うわあ～！　サーキットって、いいね！　牧場みたいな雰囲気だー！　どんな雰囲気かって？　むむむ……なんかこう、風をうけて、前へ自由に進める感じ、かなぁ？　えへへ。オオカミさん、リサリサともう一周走ろ？」",200032,2,"deco/character/ailisha_SC",false,false,1,false,false,false,false,false,false,false,false,"240,-130,1",false,"-200,0,1",1730,918,384,1230,668,2154,2283,1230,668,2154,1202,1,3786,5000,1397,2411,8000,13333,13833,14400,12000,8000,8000,"ailisha_sc"},h)g[403207]=b({e[17057],403207,4,99,196,"「わ～っ、今日の雪、ふわふわ。踏んでみると、まるで刈った羊さんの毛の山みたい！\nオオカミさん、一緒に雪だるま作ろ？ リサリサは、かわいい雪の羊さんを作るね！\nオオカミさんは、かっこよくて、いつもリサリサを守ってくれる、優しいオオカミさんを作って！ ぽややんは、指導役をお願い！\nリサリサと、オオカミさん、それにぽややんで、今日は世界でいっちばん幸せなクリスマス牧場を作っちゃおう！」",200032,2,"deco/character/ailisha_sd",false,false,false,false,false,false,false,"","ailisha_sd"},h)g[403301]=b({e[17057],403301,false,100,197,false,200033,false,"deco/character/siqiqiansuili",302002,60,false,false,false,false,124,"0.949999988","siqiqiansuili"},h)g[403302]=b({e[17057],403302,1,4,198,"「君の影響で、こうしてゆったりとした午後を過ごしているけれど……良いんだか悪いんだか。\nどうやら私も『堕ちた』ようね、ふふっ。」",200033,1,"deco/character/siqiqiansuili_0",302002,60,1,false,false,false,false,"0","siqiqiansuili_0"},h)g[403303]=b({e[13057],403303,11,57,199,"「早くしないと置いてくわよ！　……二人きりのお出かけなのに、仕事のことを優先しちゃうなんて、悪いとは思ってるわ。でもね、あれは結構な特ダネなのよ！　終わったらどこにでも付き合うから、今は許して！　ね？」",200033,2,"deco/character/siqiqiansuili_YY",false,false,1,1,"siqiqiansuili_yy"},h)g[403304]=b({e[9045],403304,2,14,200,"「さ、こっちに座って。一緒に飲みながら、日光浴を楽しみましょ。そうだ、日焼け止めを塗ってあげるわ。私の塗りの技術、しっかり肌で感じてね。後でじっくりとインタビューさせてもらうから。」",200033,2,"deco/character/siqiqiansuili_YZ",1,3858,5000,1655,3999,13333,6666,6666,13366,15000,8000,13333,"siqiqiansuili_xr"},h)g[403305]=b({e[13057],403305,13,46,201,"「噂の真偽に対する探求心は、ジャーナリストの性のようなものね。\nこの『みかんの湯』のうるおい効果がどれほどのものか……ふふっ、一緒に検証しましょうか。」",200033,2,"deco/character/siqiqiansuili_wq",false,false,1,1,"siqiqiansuili_wq"},h)